import { Box, Link, Typography } from "@mui/material";
import gsap from "gsap";
import { useEffect, useRef } from "react";

export const DesktopMenu = ({ onClose }) => {
  const menuRef = useRef(null);
  
  useEffect(() => {
    gsap.from(menuRef.current, {
      opacity: 0, // Start with 0 opacity
      y: 50, 
	ease: 'linear',
      duration: 0.3, // Duration of animation
      onComplete: () => {
        gsap.to(menuRef.current, {
			y: 0,
          opacity: 1, // Explicitly set opacity to 1 at the end
        });
		let tl = gsap.timeline();
		tl.fromTo('.menu1', {y: -20, opacity: 0}, { opacity: 1, y: 0, duration: .5 })
		tl.to('.menu1',  {marginLeft: '30%', duration: .5})
		tl.fromTo('.menu1after', {x: 0, opacity: 0}, {x: '100px', opacity: 1, duration: .5})
		tl.fromTo('.menu2', {y: -20, opacity: 0}, { opacity: 1, y: 0, duration: .5})
		tl.to('.menu2',  {marginLeft: '30%', duration: .5})
		tl.fromTo('.menu2after', {x: 0, opacity: 0}, {x: '100px', opacity: 1, duration: .5})
		tl.fromTo('.menu3', {y: -20, opacity: 0}, { opacity: 1, y: 0, duration: .5 })
		tl.to('.menu3',  {marginLeft: '30%', duration: .5})
		tl.fromTo('.menu3after', {x: 0, opacity: 0}, {x: '100px', opacity: 1, duration: .5})
      }
    });
}, []);
	const closeFunc = () => {
		let tl = gsap.timeline()
		tl.to(menuRef.current, {
			y: -20,
			opacity: 0,
			duration: 0.5,
			onComplete: () => {
			  onClose(); // Закрываем после завершения анимации
			}
		  });
	}

  return (
    <Box
      ref={menuRef}
      sx={{
        width: "100%",
        height: "100%",
        backgroundColor: "#010101",
        position: "fixed",
        top: 0,
        left: 0,
      }}
    >
      <Box
        sx={{
          borderRadius: "3px",
          position: "absolute",
          top: "200px", // Adjust this value for vertical positioning
          left: "50%",
          transform: "translateX(-50%)", // Centers the text horizontally
          width: "90%",
          maxWidth: "800px",
          textAlign: "center",
          display: "flex",
          flexDirection: "column",
          border: "2px solid #00ff00", // Default border for all sides
          borderTop: "30px solid #00ff00", // Top border with 10px thickness
        }}
      >
        <Box
          onClick={closeFunc}
          sx={{
            position: "absolute",
            top: "-30px",
            right: "5px",
            fontSize: "20px",
            color: "#010101",
            cursor: "pointer",
            fontWeight: "bold",
            borderRadius: "50%",
            width: "30px",
            height: "30px",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            zIndex: 9999, // ✅ Ensure it's above other elements
            pointerEvents: "auto", // ✅ Ensure it can be clicked
          }}
        >
          x
        </Box>
        <Typography
          sx={{
            position: "relative",
            fontFamily: "CustomFont",
            top: "-30px",
            color: "#010101",
            fontSize: "20px",
            fontWeight: "900",
          }}
        >
          Menu
        </Typography>
        <Link
		className="menu1"
          sx={{
            fontSize: "36px",
            marginBlock: "40px",
            color: "#00ff00",
            textDecoration: "none",
            cursor: "pointer",
            width: "fit-content",
            marginInline: "auto",
			display: 'flex',
			alignItems: 'center'
          }}
        >
          About Us
		  <Typography
		  className="menu1after"
		  sx={{
			fontFamily: 'CustomFont',
			fontSize: '36px',
		  }} 
		  >{'=>'}</Typography>
        </Link>
        <Link
		className="menu2"
          sx={{
            fontSize: "36px",
            marginBlock: "40px",
            color: "#00ff00",
            textDecoration: "none",
            cursor: "pointer",
            width: "fit-content",
            marginInline: "auto",
			display: 'flex',
			alignItems: 'center'
          }}
        >
          Projects
		  <Typography
		  className="menu2after"
		  sx={{
			fontFamily: 'CustomFont',
			fontSize: '36px',
		  }} 
		  >{'=>'}</Typography>
        </Link>
        <Link
		className="menu3"
          sx={{
            fontSize: "36px",
            marginBlock: "40px",
            color: "#00ff00",
            textDecoration: "none",
            cursor: "pointer",
            width: "fit-content",
            marginInline: "auto",
			display: 'flex',
			alignItems: 'center'
          }}
        >
          Contacts
		  <Typography
		  className="menu3after"
		  sx={{
			fontFamily: 'CustomFont',
			fontSize: '36px',
		  }} 
		  >{'=>'}</Typography>
        </Link>
      </Box>
    </Box>
  );
};
