import { useEffect, useState, useRef } from "react"; // Import React hooks
import gsap from "gsap"; // Import GSAP animation library
import { Box, Button, Typography } from "@mui/material";
import MenuRoundedIcon from "@mui/icons-material/MenuRounded";
import { DesktopMenu } from "../../helpers/menu/desktopMenu";
import "./delete.css";
import computer from "./images/computer.png";
import { useWindowSize } from "../../helpers/windowSize";

export const Homepage = () => {
  // State hooks for managing text index and scroll progress
  const [textIndex, setTextIndex] = useState(0);
  const [scrollProgress, setScrollProgress] = useState(0);
  const [menuOpen, setMenuOpen] = useState(false); // State to toggle menu

  const textRefLeft = useRef(null);
  const textRefRight = useRef(null);
  const isAnimating = useRef(false);
  const imgRef = useRef(null)

  const [position, setPosition] = useState({ x: 0, y: 0 });
  const [degreeX, setDegreeX] = useState(0);
  const [degreeY, setDegreeY] = useState(0);
  const { width, height } = useWindowSize();

  const handleMouseMove = (event) => {
    const { clientX, clientY } = event;
    setPosition({ x: clientX, y: clientY });
    let xTemp;
    let yTemp;

    if (2 * clientX > width) {
      xTemp = clientX - width / 2;
      let newDegreeX = (xTemp / (width / 2)) * 10; // 30° max rotation
    setDegreeX(newDegreeX);
    } else {
      xTemp = width / 2 - clientX;
      let newDegreeX = (xTemp / (width / 2)) * 10; // 30° max rotation
    setDegreeX(0 - newDegreeX);
    }


    if (2 * clientY > height) {
      yTemp = clientY - height / 2;
      let newDegreeY = (yTemp / (height / 2)) * -10;    
    setDegreeY(newDegreeY);
    } else {
      yTemp = height / 2 - clientY;
      let newDegreeY = (yTemp / (height / 2)) * -10;    
    setDegreeY(0 - newDegreeY);
    }
    
    const element = imgRef.current
    gsap.to(element, {
    transform: `perspective(800px) rotateX(${degreeX}deg) rotateY(${degreeY}deg) translate(-50%, -50%)`,
    duration: 0.4,
    ease: 'power2.out'
    })
    console.log(degreeX, degreeY)
  };

  // Phases of website development (left and right text arrays)
  const textsRight = [
    null,
    {
      phase: "Phase2",
      title: "Design",
      description:
        "In this phase, you focus on the visual aspects of the website, ensuring it aligns with the brand and user expectations",
    },
    null,
    {
      phase: "Phase4",
      title: "Content Creation",
      description:
        "This phase focuses on developing high-quality content for the website",
    },
    null,
    {
      phase: "Phase6",
      title: "Launch",
      description:
        "This phase involves making the website live and accessible to the public",
    },
    null,
    {
      phase: "Phase8",
      title: "Marketing & Optimization",
      description:
        "This phase involves promoting the website and continuously improving it for better performance and user engagement",
    },
  ];
  const textsLeft = [
    {
      phase: "Phase1",
      title: "Planning",
      description:
        "This is the initial phase where you define the website’s purpose, target audience, and functionality",
    },
    null,
    {
      phase: "Phase3",
      title: "Development",
      description:
        "This phase focuses on translating the design into a functional website through coding and backend setup",
    },
    null,
    {
      phase: "Phase5",
      title: "Testing",
      description:
        "This phase ensures the website functions properly, with no errors, and provides a good user experience",
    },
    null,
    {
      phase: "Phase7",
      title: "Post-launch Maintenance",
      description:
        "This phase focuses on keeping the website up to date and running smoothly after launch",
    },
    null,
  ];

  const SCROLL_THRESHOLD = 300; // Scroll threshold for changing text
  const lastScrollY = useRef(0); // Stores last scroll position (not used, but can be extended)

  useEffect(() => {
    const handleScroll = (event) => {
      event.preventDefault(); // Disable default scrolling behavior

      if (isAnimating.current) return; // Prevent multiple animations at once

      const delta = event.deltaY; // Get the scroll distance
      setScrollProgress((prev) => prev + delta); // Update scroll progress

      // Check if the scroll progress exceeds the threshold
      if (Math.abs(scrollProgress) >= SCROLL_THRESHOLD) {
        isAnimating.current = true; // Start animation
        setScrollProgress(0); // Reset scroll progress

        const isScrollingDown = delta > 0; // Check if scrolling down
        const nextIndex = isScrollingDown ? textIndex + 1 : textIndex - 1;

        // Prevent going below 0 or above the last valid index
        if (nextIndex < 0 || nextIndex >= textsLeft.length) {
          isAnimating.current = false;
          return;
        }
        const elements = [textRefLeft.current, textRefRight.current].filter(
          Boolean
        );

        gsap
          .to(elements, {
            opacity: 0,
            y: isScrollingDown ? -20 : 20,
            duration: 0.5,
          })
          .then(() => {
            setTextIndex(nextIndex);
            return gsap.fromTo(
              elements,
              { opacity: 0, y: 0 },
              { opacity: 1, y: 0, duration: 1 }
            );
          })

          .then(() => (isAnimating.current = false));
      }
    };

    window.addEventListener("wheel", handleScroll, { passive: false });

    return () => {
      window.removeEventListener("wheel", handleScroll);
    };
  }, [scrollProgress, textIndex, textsLeft.length]);

  return (
    <div
      onMouseMove={handleMouseMove}
      style={{
        height: "100vh", // Full viewport height
        display: "flex", // Use flexbox for layout
        alignItems: "center", // Vertically center the text
        justifyContent: "space-between", // Distribute text on left and right
        background: "black", // Black background
        color: "#00FF41", // Matrix green text color
        fontSize: "2rem", // Font size
        textAlign: "center", // Center the text
        overflow: "hidden", // Hide scrollbars
      }}
    >
      <Box
        sx={{
          position: "absolute",
          top: "20px", // Adjust this value for vertical positioning
          left: "50%",
          transform: "translateX(-50%)", // Centers the text horizontally
          width: "100%",
          textAlign: "center",
        }}
      >
        <Typography
          sx={{
            fontFamily: "CustomFont",
            fontSize: "48px", // Adjust font size as needed
            fontWeight: "bold",
            color: "#00FF41",
          }}
        >
          YurWell
        </Typography>
      </Box>
      <Box
        sx={{
          position: "absolute",
          top: "40px", // Adjust this value for vertical positioning
          left: "95%",
          transform: "translateX(-50%)", // Centers the text horizontally
          textAlign: "center",
        }}
      >
        <Button
          onClick={() => setMenuOpen(true)} // Open menu on click
          sx={{
            border: "2px solid #00ff00", // Default border for all sides
            width: "40px",
            height: "40px",
            color: "#00ff00",
            padding: "0",
            borderRadius: "50%", // Makes the button circular
            minWidth: "unset", // Ensures it doesn't stretch
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          <MenuRoundedIcon />
        </Button>
      </Box>

      {/* Left text */}
      {textsLeft[textIndex] === null ? (
        <Box></Box>
      ) : (
        <Box
          ref={textRefLeft}
          sx={{
            padding: "5px",
            borderRadius: "3px",
            marginInline: "50px",
            width: "25%",
            textAlign: "start",
            border: "2px solid #00ff00", // Default border for all sides
            borderTop: "15px solid #00ff00", // Top border with 10px thickness
            position: "relative", // Make sure the pseudo-element is positioned relative to the parent element
            "&::after": {
              content: '"x"', // The cross symbol
              position: "absolute", // Position it absolutely inside the parent
              top: "-18px", // Adjust the position of the cross
              right: "5px", // Align it to the top-right corner
              fontSize: "20px", // Set the size of the cross
              color: "#010101", // Cross color
              cursor: "pointer", // Make it clickable if you want
              fontWeight: "bold", // Optional, to make the cross thicker
            },
          }}
        >
          <Typography
            sx={{
              fontFamily: "CustomFont",
              fontSize: "24px",
            }}
          >
            {textsLeft[textIndex].phase}
          </Typography>
          <Typography
            sx={{
              fontFamily: "CustomFont",
              fontSize: "36px",
            }}
          >
            {textsLeft[textIndex].title}
          </Typography>
          <Typography
            sx={{
              fontFamily: "CustomFont",
              fontSize: "20px",
              position: "relative", // Make sure the pseudo-element is positioned relative to the text
            }}
          >
            {textsLeft[textIndex].description}
            <span className="blinking-cursor">_</span>
          </Typography>
        </Box>
      )}
      {/* Right text */}
      <img
        ref={imgRef}
        style={{
          position: "absolute",
          left: "50%",
          top: "50%",
          transformOrigin: "center",
          border: "2px solid #00ff00",
          //transform: `perspective(800px) rotateX(${degreeX}deg) rotateY(${degreeY}deg) translate(-50%, -50%)`,
        }}
        src={computer}
        alt=""
      />
      {textsRight[textIndex] === null ? (
        <Box></Box>
      ) : (
        <Box
          ref={textRefRight}
          sx={{
            borderRadius: "3px",
            padding: "5px",
            marginInline: "50px",
            width: "25%",
            textAlign: "start",
            border: "2px solid #00ff00", // Default border for all sides
            borderTop: "15px solid #00ff00", // Top border with 10px thickness
            position: "relative", // Make sure the pseudo-element is positioned relative to the parent element
            "&::after": {
              content: '"x"', // The cross symbol
              position: "absolute", // Position it absolutely inside the parent
              top: "-18px", // Adjust the position of the cross
              right: "5px", // Align it to the top-right corner
              fontSize: "20px", // Set the size of the cross
              color: "#010101", // Cross color
              cursor: "pointer", // Make it clickable if you want
              fontWeight: "bold", // Optional, to make the cross thicker
            },
          }}
        >
          <Typography
            sx={{
              fontFamily: "CustomFont",
              fontSize: "24px",
            }}
          >
            {textsRight[textIndex].phase}
          </Typography>
          <Typography
            sx={{
              fontFamily: "CustomFont",
              fontSize: "36px",
            }}
          >
            {textsRight[textIndex].title}
          </Typography>
          <Typography
            sx={{
              fontFamily: "CustomFont",
              fontSize: "20px",
              position: "relative", // Make sure the pseudo-element is positioned relative to the text
            }}
          >
            {textsRight[textIndex].description}
            <Typography
              sx={{
                fontFamily: "CustomFont",
                fontSize: "20px",
                position: "relative", // Ensure the pseudo-element is positioned relative to the text
              }}
            >
              {textsRight[textIndex].description}
              <span className="blinking-cursor">_</span>
            </Typography>
          </Typography>
        </Box>
      )}
      {menuOpen && <DesktopMenu onClose={() => setMenuOpen(false)} />}
    </div>
  );
};
